            if (innovation < 45) insights.push(window.mySimulation.t(`insight_lowinnovation`));
            if (minutes < 50) insights.push(window.mySimulation.t(`insight_rushed`));
            if (operational && relationshipHeld && innovative) insights.push(window.mySimulation.t(`insight_paradox`));

            return {
                agreement: agreement,
                relationship: relationship,
                innovation: innovation,
                minutes: minutes,
                departures: departures,
                timeScore: Math.round(timeScore),
                operational: operational,
                relationshipHeld: relationshipHeld,
                innovative: innovative,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                timeManaged: (minutes >= 55 && minutes <= this.MEETING_MINUTES + 3),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="nego-cm"><p class="nego-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="nego-cm-chip ` + (ok ? `nego-cm-ok` : `nego-cm-no`) + `">` +
                `<span class="nego-cm-ico">` + (ok ? `\u2713` : `\u2717`) + `</span>` + label + ` \u00b7 ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="nego-cm-kpi"><div class="nego-cm-kpi-val">` + val +
                `</div><div class="nego-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="nego-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="nego-cm">` +
  `<div class="nego-cm-head">` +
    `<div class="nego-cm-score"><div class="nego-cm-score-num">` + Math.round(s.composite) +
       `<span class="nego-cm-score-den">/100</span></div>` +
       `<div class="nego-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="nego-cm-verdict"><div class="nego-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="nego-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="nego-cm-section"><div class="nego-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="nego-cm-chips">` + chip(!!s.operational, t(`cm_t_operational`)) + chip(!!s.relationshipHeld, t(`cm_t_relationship`)) +
      chip(!!s.innovative, t(`cm_t_innovation`)) + chip(!!s.timeManaged, t(`cm_t_time`)) + `</div></div>` +
  `<div class="nego-cm-section"><div class="nego-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="nego-cm-kpis">` +
      kpi(t(`agreement_label`), Math.round(s.agreement), t(`cm_sub_agreement`)) +
      kpi(t(`relationship_label`), Math.round(s.relationship), t(`cm_sub_relationship`)) +
      kpi(t(`innovation_label`), Math.round(s.innovation), t(`cm_sub_innovation`)) +
      kpi(t(`time_label`), Math.round(s.minutes) + ` min`, t(`cm_sub_time`)) +
    `</div></div>` +
  (insights ? `<div class="nego-cm-section"><div class="nego-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="nego-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.relationship < 35) return window.mySimulation.t(`hint_relationship`);
            if (ds.vagueDeal) return window.mySimulation.t(`hint_vague`);
            if (state.currentPeriod >= 3 && !ds.surfacedInterests) return window.mySimulation.t(`hint_interests`);
            if (state.currentPeriod >= 3 && ds.innovation < 40) return window.mySimulation.t(`hint_innovation`);
            if (ds.agreement >= 65 && ds.relationship >= 60 && ds.innovation >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.agreement`, label: `Agreement`, i18nKey: `col_agreement`, formatter: (v) => Math.round(v) },
                { key: `results.relationship`, label: `Relationship`, i18nKey: `col_relationship`, formatter: (v) => Math.round(v) },
                { key: `results.innovation`, label: `Innovation`, i18nKey: `col_innovation`, formatter: (v) => Math.round(v) },
                { key: `results.minutesUsed`, label: `Min`, i18nKey: `col_minutes`, formatter: (v) => Math.round(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

